'use strict';
/* SUITS · telas: interface, ações e inicialização
   Scripts clássicos compartilham o escopo global (carregados em ordem pelo suits.html).
   Mapa do código e regras: CLAUDE.md na raiz do repositório. */
/* ================================================================
   TELAS
================================================================= */
const bar=(v,cls)=>`<div class="bar ${cls||''}"><div style="width:${clamp(v,0,100)}%"></div></div>`;
const bd=(t,c)=>`<span class="bd ${c||''}">${esc(t)}</span>`;
function prazoCls(ate){const n=uteisAte(S.g.date,ate);return n<=2?'er':n<=5?'wa':'ok'}
function prazoTxt(ate){const n=uteisAte(S.g.date,ate);return ate===S.g.date?'vence HOJE':n===1?'falta 1 dia útil':`faltam ${n} dias úteis`}
function fbList(items){return '<ul class="fb">'+items.map(it=>`<li class="${it.ok>=1?'y':it.ok>0?'':'n'}"><i>${it.ok>=1?'✓':it.ok>0?'~':'✗'}</i><div>${it.l?`<b>${esc(it.l)}</b>${it.c?`: ${esc(it.c)}`:''}<br>`:''}${it.t?`<span class="sm">${esc(it.t)}</span>`:''}${(it.q||[]).map(x=>`<q>${esc(x)}</q>`).join('')}${it.a&&it.a.length?`<div>${leis(it.a)}</div>`:''}</div></li>`).join('')+'</ul>'}

function vCover(){const s=load();
  return `<div class="cover"><div class="frame"></div>
  <div class="scale">${SCALE}</div><div class="kick">BNF GAMES apresenta</div>
  <h1>SUIT<i>S</i></h1><div class="tag">Da beca ao tribunal.</div>
  <div class="lines">Você saiu da faculdade com uma dívida, um diploma e um nome a construir. Passe na OAB, sente do outro lado da mesa de clientes que não dormem, conte cada prazo em dias úteis e encare, audiência após audiência, o ${RIVAL.t}.<br><br>Cada decisão tem um artigo de lei por trás. E o Vade Mecum está sempre na sua mão.</div>
  <div class="btns">${s?`<button class="btn gold" data-a="continue">Continuar carreira</button>`:''}<button class="btn ${s?'sec':'gold'}" data-a="${s?'askNew':'new'}">Nova carreira</button><a class="btn sec" href="./index.html">Voltar ao BNF GAMES</a></div>
  <div class="ver">Versão ${VERSION} · <button data-a="news">Novidades e próximas atualizações</button></div></div>`}
function vSetup(){const st=UI.setup;
  return `<div style="max-width:560px;margin:0 auto;padding:28px 16px 60px">
  <div class="ttl"><h1>Sua ficha</h1><span class="sub">Faculdade de Direito · 10º período</span></div>
  <div class="memo"><div class="mh"><b>Dados do(a) formando(a)</b><span class="xs mu">${esc(VERSION)}</span></div><div class="mb" style="font-family:var(--sans);font-size:14px">
  <label class="lbl">Nome completo</label><input class="input" data-in="nome" maxlength="40" placeholder="Como vai aparecer na carteira da OAB" value="${esc(st.nome)}">
  <div style="height:12px"></div><label class="lbl">Tratamento</label><div class="seg"><button class="${st.sx==='f'?'on':''}" data-a="sx" data-v="f">Doutora</button><button class="${st.sx==='m'?'on':''}" data-a="sx" data-v="m">Doutor</button></div>
  <div style="height:12px"></div><label class="lbl">Estado (seccional da OAB e comarca)</label><select data-ch="uf">${Object.keys(UFS).map(k=>`<option value="${k}" ${k===st.uf?'selected':''}>${UFS[k][0]} (${UFS[k][1]})</option>`).join('')}</select>
  <p class="note">Pessoas, empresas, escritórios e casos são fictícios. As leis são reais.</p></div></div>
  <div style="height:14px"></div><button class="btn full" data-a="start">Colar grau</button>
  <div style="height:8px"></div><button class="btn sec full" data-a="cover">Voltar</button></div>`}
function preBar(sub){return `<div class="side" style="position:sticky;width:100%;height:auto;flex-direction:row;justify-content:space-between;align-items:center;padding:10px 16px;bottom:auto"><div class="lg serif" style="font-weight:700;letter-spacing:.2em;color:#fff;font-size:17px">SUIT<span class="go">S</span></div><div class="row"><span class="xs" style="color:#C9AEB4">${esc(sub)}</span>${S.phase==='oab1'&&!S.ex.shown?'':`<button class="btn sm sec" data-a="vmTab">📖 Vade Mecum</button>`}</div></div>`}
function vTut(){const st=S.tut;let h=preBar('Faculdade de Direito')+'<div class="wrap" style="margin:0 auto;max-width:720px">';
  if(st===0)h+=`<div class="ttl"><h1>A última aula</h1><span class="sub">${esc(UFS[S.uf][1])} · dezembro de 2027</span></div><div class="memo"><div class="mb big"><p>O auditório já está vazio quando o professor Otaviano Brandão te chama. Setenta anos, trinta de tribuna, a gravata sempre torta.</p><p>"${g('Doutora','Doutor')} ${esc(S.nome.split(' ')[0])}... ainda não, né? Falta a Ordem." Ele sorri. "Vou te dizer o que ninguém diz na formatura: advogado não perde causa por não saber a lei. Perde por <b>perder prazo</b>, por <b>não ouvir o cliente</b> e por <b>achar que ética é matéria de prova</b>."</p><p>Ele te entrega um Vade Mecum velho, com as bordas gastas e as páginas cheias de anotação a lápis.</p><p>"Era meu. Agora é seu. Abre sempre que tiver dúvida. Abrir não custa nada. Errar custa."</p></div></div><div style="height:14px"></div><button class="btn full" data-a="tut">Continuar</button>`;
  else if(st===1)h+=`<div class="ttl"><h1>Como a carreira funciona</h1></div><div class="pn"><div class="pb"><ul class="fb">
    <li class="y"><i>⚖</i><div><b>Processos de verdade</b><br><span class="sm">Do atendimento ao cumprimento de sentença. Cada fase é uma decisão, e cada decisão tem um artigo de lei.</span></div></li>
    <li class="y"><i>⏱</i><div><b>O tempo corre em dias úteis</b><br><span class="sm">Cada dia tem 8 horas. Atender, redigir, ir à audiência: tudo gasta horas. Os prazos correm ao mesmo tempo em vários processos, e perder um é o pior erro do jogo.</span></div></li>
    <li class="y"><i>📈</i><div><b>Seis indicadores</b><br><span class="sm">Reputação, Clientes, Ética (OAB), Juízo e Estresse, além do Caixa. Acima de 80, cada ponto custa o dobro: chegar a 100 exige uma carreira inteira.</span></div></li>
    <li class="y"><i>📖</i><div><b>Vade Mecum na mão</b><br><span class="sm">Todo link 📖 abre o artigo sem sair da tela. Os artigos começam lacrados e vão abrindo à medida que aparecem.</span></div></li>
    <li class="y"><i>♟</i><div><b>Um rival</b><br><span class="sm">${RIVAL.t}, da ${RIVAL.firm}, vai estar do outro lado em muitos dos seus processos.</span></div></li></ul></div></div><div style="height:14px"></div><button class="btn full" data-a="tut">Continuar</button>`;
  else if(st===2){const pub='2027-04-16',ok=addUteis(pub,5),a=S.tutA;let cal='<div class="cal">'+['seg','ter','qua','qui','sex','sáb','dom'].map(x=>`<div class="h">${x}</div>`).join('');let d='2027-04-12';for(let i=0;i<21;i++){const cls=d===pub?'st':isFer(d)?'fe':!isWork(d)?'we':'';const res=a?(d===ok?'ok':d===a?'on':''):'';cal+=`<button class="${cls} ${res}" data-a="tutPick" data-v="${d}" ${a?'disabled':''}>${+d.slice(8)}</button>`;d=addD(d,1)}cal+='</div>';
    h+=`<div class="ttl"><h1>Treino: contar um prazo</h1><span class="sub">abril de 2027</span></div><div class="memo"><div class="mb"><p>A intimação foi publicada na <b>sexta-feira, 16/04</b> (em dourado). O prazo é de <b>5 dias úteis</b>. Toque no dia em que ele vence.</p><p class="sm mu" style="font-family:var(--sans)">Dica: o dia do começo não conta; o do vencimento conta. Sábado, domingo e feriado não contam (em vermelho, o feriado de Tiradentes).</p>${leis(['CPC-219','CPC-224'])}<div style="height:10px"></div>${cal}</div>
    ${a?`<div class="desp">${a===ok?`<div class="alert ok"><div><b>Certo: vence em ${fmtL(ok)}.</b>Começa a contar na segunda (19), pula o feriado de quarta (21): 19, 20, 22, 23 e 26.</div></div>`:`<div class="alert er"><div><b>Não. Vence em ${fmtL(ok)}.</b>Exclui o dia da publicação, conta só dias úteis e pula o feriado de 21/04: 19, 20, 22, 23 e 26.</div></div><button class="btn sec full" data-a="tutRetry" style="margin-bottom:8px">Tentar de novo</button>`}<button class="btn full" data-a="tut">Continuar</button></div>`:''}</div>`}
  else h+=`<div class="ttl"><h1>O Exame de Ordem</h1></div><div class="memo"><div class="mb"><p>Sem aprovação no Exame de Ordem, não há inscrição na OAB.</p>${leis(['EAOAB-8'])}<p style="margin-top:10px"><b>1ª fase:</b> 20 questões objetivas. Aprova com 10 acertos: a mesma proporção do exame real (40 de 80). Você tem 40 minutos.</p><p><b>2ª fase (Civil):</b> uma peça no Montador, valendo 5 pontos, e 4 questões de fundamento, valendo 1,25 cada. Aprova com 6.</p><p class="sm mu" style="font-family:var(--sans)">Questões escritas para o jogo, no estilo do exame. Reprovou? Tenta no próximo, quatro meses depois.</p></div></div><div style="height:14px"></div><button class="btn full" data-a="oab1">Entrar na sala de prova</button>`;
  return h+'</div>'}
function timerH(dl,tot){const left=Math.max(0,dl-Date.now());return `<div class="timer ${left<tot*.15?'low':''}" id="tx"><b id="tt">${fmtT(left)}</b><div class="tb"><div id="tb" style="width:${left/tot*100}%"></div></div></div>`}
const fmtT=ms=>{const s=Math.ceil(ms/1000);return String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0')};
const QT=40*60e3,PT=15*60e3;
function vOab1(){const E=S.ex,q=QB[E.q[E.i]],pm=E.perm[E.i],ans=E.ans[E.i];let h=preBar(`${S.exN+1}º Exame de Ordem · 1ª fase`)+'<div class="wrap" style="margin:0 auto;max-width:720px">';
  h+=timerH(E.dl,QT)+`<div class="prog">${E.q.map((_,i)=>`<div class="${i<E.i?'dn':i===E.i?'on':''}"></div>`).join('')}</div>`;
  h+=`<div class="memo"><div class="mh"><b>Questão ${E.i+1} de 20</b>${bd(DISC[q.d],'pr')}</div><div class="mb"><p>${esc(q.q)}</p></div><div class="desp">`;
  pm.forEach((oi,k)=>{const on=ans===oi,shown=E.shown;let cls='';if(shown){if(oi===q.c)cls='on';else if(on)cls='on'}h+=`<button class="ro ${cls}" data-a="ans1" data-v="${k}" ${shown?'disabled':''} style="${shown&&oi===q.c?'border-color:var(--ok);background:var(--ok2)':shown&&on?'border-color:var(--er);background:var(--er2)':''}"><i></i><div><b>${'ABCD'[k]}) ${esc(q.o[oi])}</b></div></button>`});
  if(E.shown){const ok=ans===q.c;h+=`<div class="alert ${ok?'ok':'er'}" style="margin-top:8px"><div><b>${ok?'Correta.':ans===-1?'Tempo esgotado.':'Incorreta.'}</b>${esc(q.e)}<div style="margin-top:6px">${lei(q.a)}</div></div></div><button class="btn full" data-a="next1">${E.i<19?'Próxima questão':'Entregar a prova'}</button>`}
  return h+'</div></div></div>'}
function vOab1Res(){const E=S.ex,n=E.ans.filter((a,i)=>a===QB[E.q[i]].c).length,ok=n>=10;const by={};E.q.forEach((qi,i)=>{const d=QB[qi].d;by[d]=by[d]||[0,0];by[d][1]++;if(E.ans[i]===QB[qi].c)by[d][0]++});
  let h=preBar('Resultado da 1ª fase')+'<div class="wrap" style="margin:0 auto;max-width:720px">';
  h+=`<div class="memo"><div class="mh"><b>Ordem dos Advogados do Brasil · Resultado</b><span class="mono xs">${S.exN+1}º exame</span></div><div class="mb"><p style="font-size:30px;margin:0" class="mono">${n}/20</p><p class="${ok?'ok':'er'}" style="font-weight:600">${ok?'APROVADO(A) NA 1ª FASE':'NÃO APROVADO(A)'}</p><p class="sm mu" style="font-family:var(--sans)">Mínimo: 10 acertos (50%, como no exame real).</p></div></div>`;
  h+=`<div class="pn"><h3>Por disciplina</h3><div class="tw"><table>${Object.keys(by).map(d=>`<tr><td>${DISC[d]}</td><td class="mono" style="text-align:right">${by[d][0]}/${by[d][1]}</td></tr>`).join('')}</table></div></div><div style="height:14px"></div>`;
  h+=`<details class="pn" style="margin-bottom:14px"><summary class="pb b" style="cursor:pointer">Ver gabarito comentado</summary><div class="pb" style="padding-top:0">${E.q.map((qi,i)=>{const q=QB[qi],a=E.ans[i];return `<div style="padding:10px 0;border-top:1px solid var(--ln2)"><div class="xs mu">${i+1}. ${DISC[q.d]}</div><b class="sm">${esc(q.q)}</b><div class="sm ${a===q.c?'ok':'er'}">${a===q.c?'✓ Você acertou':'✗ Sua resposta: '+(a>=0?esc(q.o[a]):'em branco')}</div><div class="sm">Correta: <b>${esc(q.o[q.c])}</b>. ${esc(q.e)}</div>${lei(q.a)}</div>`}).join('')}</div></details>`;
  h+=ok?`<button class="btn full" data-a="oab2">Seguir para a 2ª fase</button>`:`<div class="alert er"><div><b>Faz parte.</b>O próximo exame é daqui a quatro meses. A inscrição custa R$ 300 e o estresse sobe.</div></div><button class="btn full" data-a="retry1">Estudar e tentar o próximo exame</button>`;
  return h+'</div>'}
function vOab2(){const P=S.p2;let h=preBar('2ª fase · Prático-profissional (Civil)')+'<div class="wrap" style="margin:0 auto;max-width:760px">';
  if(P.st==='peca'){h+=timerH(P.dl,PT)+`<div class="alert pr"><div><b>Enunciado</b>${esc(P.c.cli.n)} teve o nome negativado pela ${esc(P.c.v.emp)} por uma dívida de ${money(P.c.v.div)} de uma linha que nunca contratou, e teve o crédito negado em público. Não há outras negativações. Elabore a petição inicial no Juizado Especial Cível.</div></div>`+vMont(P.c,'exam')}
  else{const D=P.disc,q=D2[D.q[D.i]],a=D.ans[D.i],pm=(D.perm&&D.perm[D.i])||[0,1,2,3];h+=`<div class="prog">${D.q.map((_,i)=>`<div class="${i<D.i?'dn':i===D.i?'on':''}"></div>`).join('')}</div><div class="memo"><div class="mh"><b>Questão ${D.i+1} de 4 · 1,25 ponto</b><span class="xs mu">Peça: ${f2(P.sc*5)}/5</span></div><div class="mb"><p>${esc(q.q)}</p></div><div class="desp">${pm.map((i,k)=>{const o=q.o[i];return `<button class="ro ${a===i?'on':''}" data-a="ans2" data-v="${k}" ${a!=null?'disabled':''} style="${a!=null&&i===q.c?'border-color:var(--ok);background:var(--ok2)':a===i&&i!==q.c?'border-color:var(--er);background:var(--er2)':''}"><i></i><div><b>${'ABCD'[k]}) ${esc(o)}</b></div></button>`}).join('')}
    ${a!=null?`<div class="alert ${a===q.c?'ok':'er'}"><div><b>${a===q.c?'Correto.':'Incorreto.'}</b>${esc(q.e||'')}<div style="margin-top:4px">${lei(q.a)}</div></div></div><button class="btn full" data-a="next2">${D.i<3?'Próxima':'Entregar'}</button>`:''}</div></div>`}
  return h+'</div>'}
const f1=x=>(Math.floor(x*10+1e-9)/10).toFixed(1).replace('.',',');
const f2=x=>(Math.round(x*100)/100).toFixed(2).replace('.',',');
function vOab2Res(){const P=S.p2,n=P.disc.ans.filter((a,i)=>a===D2[P.disc.q[i]].c).length,tot=P.sc*5+n*1.25,ok=tot>=6;
  let h=preBar('Resultado final')+'<div class="wrap" style="margin:0 auto;max-width:720px">';
  h+=`<div class="memo"><div class="mh"><b>Resultado da 2ª fase</b></div><div class="mb"><p style="font-size:30px;margin:0" class="mono">${f2(tot)}</p><p class="${ok?'ok':'er'}" style="font-weight:600">${ok?'APROVADO(A) NO EXAME DE ORDEM':'NÃO APROVADO(A)'}</p><p class="sm" style="font-family:var(--sans)">Peça: ${f2(P.sc*5)}/5 · Questões: ${f2(n*1.25)}/5 · Mínimo: 6,00</p></div></div>`;
  if(P.res)h+=`<div class="pn"><h3>Correção da peça, bloco a bloco</h3><div class="pb">${blocksFb(P.res)}</div></div>`;
  h+=`<div class="pn"><h3>Questões comentadas</h3><div class="pb">${P.disc.q.map((qi,i)=>{const q=D2[qi],a=P.disc.ans[i];return `<div style="padding:8px 0;border-top:1px solid var(--ln2)"><b class="sm">${esc(q.q)}</b><div class="sm ${a===q.c?'ok':'er'}">${a===q.c?'✓ Correta':'✗ Incorreta'}</div><div class="sm">Resposta: <b>${esc(q.o[q.c])}</b>. ${esc(q.e||'')}</div>${lei(q.a)}</div>`}).join('')}</div></div><div style="height:14px"></div>`;
  h+=ok?`<button class="btn gold full" data-a="posse">Ir para a cerimônia de compromisso</button>`:`<button class="btn full" data-a="retry2">Tentar a 2ª fase no próximo exame</button>`;return h+'</div>'}
function vPosse(){const a=getArt('RG-20');unlock('RG-20');unlock('EAOAB-8');return preBar('Seccional '+S.uf)+`<div class="wrap" style="margin:0 auto;max-width:680px"><div class="memo"><div class="mh"><b>Ordem dos Advogados do Brasil · Seção ${UFS[S.uf][0]}</b></div><div class="mb big"><p>O salão da Seccional cheira a madeira encerada. Sua mãe está na terceira fila, com o celular erguido desde antes de começar. O presidente pede que os novos advogados fiquem de pé e repitam:</p><p class="say">${esc(a.t.split('"')[1])}</p>${leis(['RG-20','EAOAB-8'])}</div><div class="desp"><button class="btn gold full" data-a="prometo">Prometo</button></div></div></div>`}

/* ---------- casca da carreira ---------- */
function navCount(k){const G=S.g;if(k==='processos')return casesOpen().filter(needs).length;if(k==='prazos')return casesOpen().filter(c=>c.prazo&&uteisAte(G.date,c.prazo.ate)<=2).length;return 0}
const TABS=[['painel','Painel'],['processos','Processos'],['prazos','Prazos'],['clientes','Clientes'],['escritorio','Escritório'],['vade','Vade Mecum'],['oab','OAB']];
function shell(inner){const G=S.g,last=S.nome.split(' ').slice(-1)[0];
  let h=`<div class="side"><div class="brandbox"><div class="lg">SUIT<i>S</i></div><div class="who"><b>${DR()} ${esc(S.nome)}</b><br>${esc(G.oab)} · ${G.cargo==='assoc'?'Associad'+g('a','o'):'Advogad'+g('a','o')}<br>${MENTOR.firm}</div></div>
  <div class="mobhd"><div class="lg">SUIT<i>S</i></div><span>${DR()} ${esc(last)}<br>${fmtL(G.date)} · ${fmtH(G.h)}</span></div>
  <nav class="nav">${TABS.map(([k,l])=>{const n=navCount(k);return `<button class="${UI.tab===k&&!UI.open?'on':''}" data-a="tab" data-v="${k}"><span>${l}</span>${n?`<i class="${k==='prazos'?'r':''}">${n}</i>`:''}</button>`}).join('')}</nav>
  <div class="sfoot"><button data-a="news">Novidades (v${VERSION})</button><button data-a="mute">${UI.mute?'Som: desligado':'Som: ligado'}</button><button data-a="askNew">Nova carreira</button><button data-a="cover">Sair para a capa</button></div></div>`;
  h+=`<div class="main"><div class="ibar">${['rep','cli','et','jz','st'].map(k=>`<div><label>${IND[k]}</label><b>${Math.round(G.ind[k])}</b>${bar(G.ind[k],k==='st'?'st':'')}</div>`).join('')}<div><label>Caixa</label><b class="${G.cx<0?'er':''}">${money(G.cx)}</b></div><div><label>Vade Mecum</label><b>${S.vm.n||0}/${VTOT}</b></div></div><div class="wrap">${inner}</div></div>`;
  const night=G.h<5&&!G.night;
  h+=`<div class="foot"><div><div class="inf"><b>${fmtL(G.date)}</b> · ${isRec(G.date)?'<span class="wa b">recesso forense</span> · ':''}Horas hoje: <b>${fmtH(G.h)}</b>${G.night?' (virou a noite)':''}</div>${night?`<button class="btn sec sm" data-a="night" title="+4h, estresse +7">Virar a noite</button>`:''}<button class="btn sec sm" data-a="ff" title="Avança até algo acontecer">Avançar ▸▸</button><button class="btn sm" data-a="end">Encerrar o dia</button></div></div>`;
  return h}

function vPainel(){const G=S.g,open=casesOpen(),pend=open.filter(needs),today=open.filter(c=>c.aud&&c.aud.d===G.date&&!c.aud.ok);
  const soon=open.filter(c=>c.prazo).sort((a,b)=>a.prazo.ate<b.prazo.ate?-1:1);
  let h=`<div class="ttl"><h1>Bom dia, ${DR()} ${esc(S.nome.split(' ').slice(-1)[0])}</h1><span class="sub">${fmtExt(G.date)}${isRec(G.date)?' · recesso: prazos suspensos e sem audiências':''}</span></div>`;
  if(today.length)h+=today.map(c=>`<div class="alert er"><div><b>Hoje: ${c.aud.tp==='conc'?'audiência de conciliação':'audiência de instrução'}</b>${esc(c.cli.n)} · ${esc(vara(c))}. <button class="lnk" data-a="open" data-v="${c.id}">Entrar na sala</button></div></div>`).join('');
  h+=`<div class="grid2"><div class="pn"><h3>Sua mesa <span>${pend.length} pendente${pend.length===1?'':'s'}</span></h3>${pend.length?pend.map(c=>`<button class="li" data-a="open" data-v="${c.id}"><div class="av">${face(c.cli.n,c.cli.f)}</div><div class="t"><b>${esc(c.cli.n)}</b><span>${esc(TPL[c.t].nome)} · ${esc(c.fb?'Ver resultado':FASE[c.fase])}</span></div>${c.prazo?bd(prazoTxt(c.prazo.ate),prazoCls(c.prazo.ate)):''}</button>`).join(''):'<div class="empty">Nada pendente. Avance o tempo ou estude o Vade Mecum.</div>'}</div>
  <div class="pn"><h3>Prazos <span>dias úteis</span></h3>${soon.length?soon.slice(0,5).map(c=>`<button class="li" data-a="open" data-v="${c.id}"><div class="t"><b>${esc(c.prazo.lbl)}</b><span class="mono">${numD(c)}</span></div>${bd(fmtDs(c.prazo.ate)+' · '+prazoTxt(c.prazo.ate),prazoCls(c.prazo.ate)+(uteisAte(G.date,c.prazo.ate)<=2?' pulse':''))}</button>`).join(''):'<div class="empty">Nenhum prazo correndo.</div>'}</div></div>`;
  h+=`<div style="height:12px"></div><div class="grid2"><div class="pn"><h3>Recados</h3>${G.msgs.length?G.msgs.slice(0,5).map(m=>`<div class="msg"><div class="h"><b>${esc(m.from)}</b><span class="mono">${fmtDs(m.d)}</span></div><p>${esc(m.txt)}</p></div>`).join(''):'<div class="empty">Sem recados.</div>'}</div>
  <div class="pn"><h3>O rival</h3><div class="vs"><div class="av">${face(RIVAL.n,false,'#D8CBBF')}</div><div class="t" style="flex:1"><b>${RIVAL.t}</b><div class="xs mu">${RIVAL.firm} · 22 anos de tribunal</div></div><div class="sc">${G.rival.w}<span class="mu">–</span>${G.rival.l}</div></div><div class="pb sm mu" style="padding-top:0">${G.rival.w>G.rival.l?'"Sorte de principiante", ele diz a quem pergunta. Mas já não sorri quando te vê no corredor.':G.rival.l>G.rival.w?'Ele te cumprimenta pelo nome agora. Com aquele sorriso de quem já sabe o fim.':'Ele ainda não sabe o seu nome. Isso vai mudar.'}</div></div></div>`;
  return h}
function vProcessos(){const G=S.g,open=casesOpen(),done=G.cases.filter(c=>c.done);
  const row=c=>`<tr class="ck" data-a="open" data-v="${c.id}"><td class="mono xs">${numD(c)}</td><td><b>${esc(c.cli.n)}</b><div class="xs mu">${esc(TPL[c.t].nome)} · ${c.lado==='autor'?'autor':'réu'}</div></td><td>${c.done?bd(c.how==='acordo'?'acordo':c.win>=1?'ganhou':c.win>0?'parcial':'perdeu',c.win>=1?'ok':c.win>0?'wa':'er'):esc(c.fb?'Resultado':FASE[c.fase])}</td><td>${c.prazo?bd(fmtDs(c.prazo.ate),prazoCls(c.prazo.ate)):c.aud?bd('aud. '+fmtDs(c.aud.d),'pr'):c.wait?'<span class="xs mu">aguardando</span>':''}</td></tr>`;
  return `<div class="ttl"><h1>Processos</h1><span class="sub">${open.length} em andamento</span></div><div class="pn"><div class="tw"><table><tr><th>Número</th><th>Cliente</th><th>Fase</th><th>Prazo</th></tr>${open.map(row).join('')||'<tr><td colspan="4" class="empty">Nenhum processo em andamento.</td></tr>'}</table></div></div>${done.length?`<div class="pn"><h3>Encerrados</h3><div class="tw"><table>${done.map(row).join('')}</table></div></div>`:''}`}
const prazoAct=c=>c.prazo&&{saneamento:'Apresentar rol',contest:'Redigir contestação',replica:'Fazer réplica',emenda:'Emendar a inicial',agravo:'Agravar',recurso:'Decidir o recurso',embargos:'Ver a sentença',cumpr:'Pedir cumprimento',contrarraz:'Contrarrazoar'}[c.prazo.tp];
function vPrazos(){const G=S.g,L=[];casesOpen().forEach(c=>{if(c.prazo)L.push({d:c.prazo.ate,t:c.prazo.lbl,c,k:'p',a:c.prazo.a});if(c.aud)L.push({d:c.aud.d,t:c.aud.tp==='conc'?'Audiência de conciliação':'Audiência de instrução',c,k:'a'})});L.sort((a,b)=>a.d<b.d?-1:1);
  return `<div class="ttl"><h1>Agenda de prazos</h1><span class="sub">Verde: mais de 5 dias úteis · Amarelo: até 5 · Vermelho: até 2</span></div>
  <div class="alert pr"><div><b>Como o jogo conta</b>Só dias úteis. Exclui o dia da publicação e inclui o do vencimento. De 20/12 a 20/01, os prazos ficam suspensos.<div>${leis(['CPC-219','CPC-220','CPC-224'])}</div></div></div>
  <div class="pn">${L.length?L.map(x=>`<div class="li"><div class="t"><b>${esc(x.t)}</b><span>${esc(x.c.cli.n)} · <span class="mono">${numD(x.c)}</span></span><div style="margin-top:4px">${x.k==='p'?bd(fmtL(x.d)+' · '+prazoTxt(x.d),prazoCls(x.d)+(uteisAte(G.date,x.d)<=2?' pulse':'')):bd(fmtL(x.d),'pr')}</div></div><button class="btn sm ${x.k==='p'?'':'sec'}" data-a="open" data-v="${x.c.id}">${x.k==='p'?esc(prazoAct(x.c)||'Cumprir'):'Ver processo'}</button></div>`).join(''):'<div class="empty">Agenda livre.</div>'}</div>`}
function vClientes(){const G=S.g;return `<div class="ttl"><h1>Clientes</h1><span class="sub">Satisfação média: ${Math.round(G.ind.cli)}</span></div><div class="pn">${G.cases.length?G.cases.map(c=>`<button class="li" data-a="open" data-v="${c.id}"><div class="av">${face(c.cli.n,c.cli.f)}</div><div class="t"><b>${esc(c.cli.n)}</b><span>${c.cli.idade} anos · ${esc(c.cli.prof)} · ${esc(TPL[c.t].nome)}</span><span>${c.hon?(c.hon.fixo?'Honorários fixos de '+money(c.hon.fixo):Math.round(c.hon.pct*100)+'% do êxito')+(c.hon.verbal?' (combinado verbal)':''):'Contrato ainda não assinado'}</span></div><div style="width:84px"><div class="xs mu">satisfação <b class="mono">${Math.round(c.sat)}</b></div>${bar(c.sat)}</div></button>`).join(''):'<div class="empty">Nenhum cliente ainda.</div>'}</div>`}
function vEscritorio(){const G=S.g,st=G.stats;return `<div class="ttl"><h1>${MENTOR.firm}</h1><span class="sub">Você é associad${g('a','o')}: salário de R$ 1.050/semana + 25% dos honorários que gerar</span></div>
  <div class="pn"><div class="kv k4"><div><label>Caixa</label><b>${money(G.cx)}</b></div><div><label>Sua parte em honorários</label><b>${money(G.earn)}</b></div><div><label>Honorários gerados</label><b>${money(G.fee)}</b></div><div><label>Semanas de casa</label><b>${G.week}</b></div><div><label>Vitórias</label><b>${st.won}</b></div><div><label>Parciais</label><b>${st.part}</b></div><div><label>Acordos</label><b>${st.acc}</b></div><div><label>Derrotas</label><b>${st.lost}</b></div><div><label>Prazos perdidos</label><b class="${st.miss?'er':''}">${st.miss}</b></div><div><label>Casos encerrados</label><b>${st.closed}</b></div><div><label>Você x ${RIVAL.n.split(' ')[1]}</label><b>${G.rival.w}–${G.rival.l}</b></div><div><label>Estresse</label><b>${Math.round(G.ind.st)}</b></div></div></div>
  <div class="pn"><h3>Carreira</h3><div class="pb"><ul class="fb"><li class="y"><i>✓</i><div><b>Exame de Ordem e inscrição</b><br><span class="sm">${esc(G.oab)}</span></div></li><li class="${G.cargo==='assoc'?'':'y'}"><i>${G.cargo==='assoc'?'●':'✓'}</i><div><b>Associad${g('a','o')} na ${MENTOR.firm}</b><br><span class="sm">Recebe casos da sócia e aprende o ofício.</span></div></li><li><i>○</i><div><b>Advogad${g('a','o')} autônom${g('a','o')}</b> ${bd('próxima atualização','go')}<br><span class="sm">Captar clientes, definir honorários e abrir o próprio escritório.</span></div></li><li><i>○</i><div><b>Sóci${g('a','o')} e especialista</b> ${bd('em breve','go')}<br><span class="sm">Equipe, estagiários e causas maiores.</span></div></li></ul></div></div>
  <div class="pn"><h3>Movimento</h3>${G.log.length?G.log.slice(0,12).map(l=>`<div class="msg"><div class="h"><span class="mono">${fmtD(l.d)}</span></div><p class="sm" style="font-family:var(--sans)">${esc(l.t)}</p></div>`).join(''):'<div class="empty">Sem movimento.</div>'}</div>`}
function vOAB(){const G=S.g,lv=G.tedLv||0;return `<div class="ttl"><h1>Situação na OAB</h1><span class="sub">${esc(G.oab)}</span></div>
  <div class="pn"><div class="kv"><div><label>Inscrição</label><b class="mono">${esc(G.oab)}</b></div><div><label>Situação</label><b class="${lv?'er':'ok'}">${['Regular','Censurad'+g('a','o'),'Suspens'+g('a','o'),'Excluíd'+g('a','o')][lv]}</b></div><div><label>Ética</label><b>${Math.round(G.ind.et)}/100</b>${bar(G.ind.et)}</div><div><label>Representações</label><b>${G.inf}</b></div></div></div>
  <div class="pn"><h3>Histórico disciplinar</h3>${G.ted.length?G.ted.map(t=>`<div class="msg"><div class="h"><span class="mono">${fmtD(t.d)}</span></div><p class="sm" style="font-family:var(--sans)">${esc(t.t)}</p></div>`).join(''):'<div class="empty">Nenhuma ocorrência. Continue assim.</div>'}</div>
  <div class="alert pr" style="margin-top:12px"><div><b>Como funciona aqui</b>Duas representações geram censura; quatro, suspensão; seis, exclusão dos quadros, que encerra a carreira.<div>${leis(['EAOAB-35','EAOAB-36','EAOAB-38'])}</div></div></div>`}
function vVade(){const q=norm(UI.vq).trim(),fav=UI.vf;let list=[];
  Object.keys(VADE).forEach(c=>{if(UI.vc&&UI.vc!==c)return;Object.keys(VADE[c].arts).forEach(a=>{const key=c+'-'+a,A=VADE[c].arts[a];if(fav&&!S.vm.fav[key])return;
    if(q){const hay=norm(refL(key)+' '+VADE[c].sh+' '+a+' '+A.r+' '+(A.tg||[]).join(' ')+' '+(S.vm.seen[key]?A.t:''));const terms=q.replace(/art\.?|artigo/g,' ').split(/\s+/).filter(Boolean);if(!terms.every(t=>hay.includes(t)))return}list.push(key)})});
  let h=`<div class="ttl"><h1>Vade Mecum</h1><span class="sub">${S.vm.n||0} de ${VTOT} artigos estudados</span></div>${bar((S.vm.n||0)/VTOT*100)}<div style="height:12px"></div>
  <input class="input" data-in="vq" placeholder='Buscar: "CPC 335", "revelia", "prazo"...' value="${esc(UI.vq)}"><div style="height:8px"></div>
  <div class="row"><div class="seg" style="flex-wrap:wrap"><button class="${!UI.vc?'on':''}" data-a="vc" data-v="">Todos</button>${Object.keys(VADE).map(c=>`<button class="${UI.vc===c?'on':''}" data-a="vc" data-v="${c}">${esc(VADE[c].sh)}</button>`).join('')}</div><button class="btn sm ${fav?'':'sec'}" data-a="vf">★ Favoritos</button></div><div style="height:12px"></div>
  <div class="pn" id="vlist">${list.length?list.map(k=>{const A=getArt(k),on=S.vm.seen[k];return `<button class="li" data-a="${on?'vm':'locked'}" data-v="${k}"><div class="t"><b>${esc(refL(k))} ${S.vm.fav[k]?'<span class="go">★</span>':''}</b><span>${on?esc(A.r):'Lacrado: abre quando aparecer no jogo'}</span></div>${on?'':'<span class="mu">🔒</span>'}</button>`}).join(''):'<div class="empty">Nada encontrado.</div>'}</div>
  <p class="note">Textos de lei não têm direito autoral (Lei 9.610/98, art. 8º, IV). Nesta versão, os textos foram transcritos para o jogo e estão marcados para conferência na fonte oficial. Na dúvida, vale o texto publicado no Planalto e no site do CFOAB.</p>`;return h}
function hlText(key,t){const H=(S.vm.hl[key]||[]).slice().sort((a,b)=>b.length-a.length);let out=esc(t);H.forEach(x=>{const e=esc(x);if(e&&out.includes(e))out=out.split(e).join('<mark>'+e+'</mark>')});return out}
function vDrawer(){const A=getArt(UI.vm);if(!A)return '';const C=VADE[A.c];unlock(A.key);
  return `<div class="ov" data-a="vmClose" style="background:rgba(26,8,12,.35)"></div><div class="drw"><div class="dh"><b>📖 ${esc(refL(A.key))}</b><button class="btn sm sec" data-a="vmClose">Fechar</button></div><div class="db">
  <div class="xs mu">${esc(C.nome)}</div><div class="b" style="margin:4px 0 10px">${esc(A.r)}</div>
  <div class="art" id="arttxt">${hlText(A.key,A.t)}</div>
  <div class="row" style="margin-top:14px"><button class="btn sm ${S.vm.fav[A.key]?'gold':'sec'}" data-a="fav" data-v="${A.key}">★ ${S.vm.fav[A.key]?'Favorito':'Favoritar'}</button><button class="btn sm sec" data-a="hl" data-v="${A.key}">Grifar a seleção</button>${(S.vm.hl[A.key]||[]).length?`<button class="btn sm sec" data-a="unhl" data-v="${A.key}">Limpar grifos</button>`:''}</div>
  <p class="note">Selecione um trecho do texto e toque em "Grifar a seleção".</p>
  <div class="alert" style="margin-top:12px"><div><b class="vtag">Texto transcrito: conferência pendente</b>Confira na fonte oficial: <a class="lnk" href="${esc(C.fonte)}" target="_blank" rel="noopener">${esc(C.fonte.replace('https://','').split('/')[0])}</a>${C.warn?'. A numeração dos artigos deste código também precisa ser conferida.':''}</div></div></div></div>`}

/* ---------- processo ---------- */
function blocksFb(res){return res.map(r=>`<div style="margin-bottom:10px"><div class="row"><b class="sm">${esc(r.t)}</b><span class="sp"></span>${bd(f1(r.s*10)+'/10',r.s>=.85?'ok':r.s>=.5?'wa':'er')}</div><ul class="fb">${r.fb.map(f=>`<li class="${f[0]>=1?'y':f[0]>0?'':'n'}"><i>${f[0]>=1?'✓':f[0]>0?'~':'✗'}</i><div class="sm">${esc(f[1])}${f[2]&&f[2].length?`<div>${leis(f[2])}</div>`:''}</div></li>`).join('')}</ul></div>`).join('')}
function vMont(c,ctx){mInit(c);const B=montBlocks(c),i=c.m.i,b=B[i],a=c.m.a[b.k];const peca=ctx==='exam'?'Petição inicial':ctx==='emenda'?'Emenda da inicial':TPL[c.t].peca==='inicial'?'Petição inicial':'Contestação';
  let h=`<div class="memo"><div class="mh"><b>Montador de Peças · ${peca}</b><span class="xs mu">Bloco ${i+1} de ${B.length}</span></div><div class="mb" style="font-family:var(--sans);font-size:14px">
  <div class="stepper">${B.map((x,j)=>ctx==='emenda'&&!c.m.em.includes(x.k)?'':`<span class="${j===i?'on':j<i?'dn':''}">${j+1}. ${esc(x.t)}</span>`).join('')}</div>
  <div class="row" style="margin-bottom:8px"><b>${esc(b.t)}</b><span class="sp"></span>${leis(b.a)}</div>${b.note?`<div class="alert pr" style="margin-bottom:10px"><div>${esc(b.note)}</div></div>`:''}`;
  const SEED=(c.id||('ex'+S.exN))+b.k;
  if(b.k==='end'||b.k==='prelim')h+=sord(SEED,b.opts.length).map(j=>{const o=b.opts[j];return `<button class="ro ${a.sel===j?'on':''}" data-a="mSel" data-v="${j}"><i></i><div><b class="serif" style="font-weight:400">${esc(o.l)}</b></div></button>`}).join('');
  else if(b.k==='qual'||b.k==='fund'||b.k==='ped'||b.k==='prov'){const items=b.k==='qual'?b.items:b.opts;h+=`<p class="xs mu" style="margin:0 0 8px">${b.k==='qual'?'Marque os dados que a petição precisa trazer sobre as partes.':b.k==='fund'?'Escolha de 2 a 4. Cuidado: há pegadinhas.':b.k==='ped'?'Marque só o que decorre dos fatos.':'Marque as provas úteis.'}</p>`+sord(SEED,items.length).map(j=>{const o=items[j];return `<button class="ro cb ${a.ch[j]?'on':''}" data-a="mChk" data-v="${j}"><i></i><div><b style="font-weight:500">${esc(o.l)}</b></div></button>`}).join('')}
  else if(b.k==='fatos'){const it=id=>b.items.find(x=>x.id===id);h+=`<p class="xs mu" style="margin:0 0 8px">Ordene os fatos (↑ ↓) e descarte o que não ajuda o cliente.</p>`+a.ord.map((id,j)=>{const f=it(id),off=a.off[id];return `<div class="fact ${off?'off':''}"><div class="mv"><button data-a="mUp" data-v="${j}" ${j===0?'disabled':''}>↑</button><button data-a="mDn" data-v="${j}" ${j===a.ord.length-1?'disabled':''}>↓</button></div><div><span class="n">${j+1}.</span> ${esc(f.t)}</div><button class="btn sm ${off?'':'sec'}" data-a="mOff" data-v="${id}">${off?'Usar':'Descartar'}</button></div>`}).join('')}
  else if(b.k==='imp')h+=`<p class="xs mu" style="margin:0 0 8px">Para cada fato da inicial do autor: impugnar ou admitir?</p>`+b.items.map((it,j)=>`<div class="fact" style="grid-template-columns:1fr auto"><div>${esc(it.t)}</div><div class="seg"><button class="${a.v[j]===1?'on':''}" data-a="mImp" data-v="${j}:1">Impugnar</button><button class="${a.v[j]===0?'on':''}" data-a="mImp" data-v="${j}:0">Admitir</button></div></div>`).join('');
  else if(b.k==='valor'){const V=valorOpts(c);h+=`<p class="xs mu" style="margin:0 0 8px">Some os pedidos com valor econômico que você marcou.</p>`+V.opts.map(v=>`<button class="ro ${a.sel===v?'on':''}" data-a="mVal" data-v="${v}"><i></i><div><b class="mono">${money(v)}</b></div></button>`).join('')}
  const last=i===B.length-1;
  h+=`</div><div class="desp"><div class="row"><button class="btn sec" data-a="mPrev" ${i===0||(ctx==='emenda'&&B.findIndex(x=>c.m.em.includes(x.k))===i)?'disabled':''}>Voltar</button><span class="sp"></span>${ctx==='emenda'?(B.findIndex((x,j)=>j>i&&c.m.em.includes(x.k))<0?`<button class="btn gold" data-a="mEmenda">Protocolar a emenda (2h)</button>`:`<button class="btn" data-a="mNext">Próximo bloco</button>`):last?`<button class="btn gold" data-a="${ctx==='exam'?'mExam':'mProt'}">${ctx==='exam'?'Entregar a peça':'Protocolar (5h)'}</button>`:`<button class="btn" data-a="mNext">Próximo bloco</button>`}</div></div></div>`;return h}
function vForm(c){const F=formDef(c),ans=c.fa||{};let h=`<div class="memo"><div class="mh"><b>${esc(F.tit)}</b><span class="xs mu">${F.hrs}h</span></div><div class="mb" style="font-family:var(--sans);font-size:14px"><p class="sm" style="margin:0 0 6px">${esc(F.intro||'')}</p>${F.a?leis(F.a):''}`;
  F.groups.forEach(gr=>{h+=`<div style="margin-top:14px"><label class="lbl">${esc(gr.l)}</label>`+sord(c.id+c.fase+gr.id,gr.opts.length).map(j=>{const o=gr.opts[j];return `<button class="ro ${ans[gr.id]===j?'on':''}" data-a="fSel" data-v="${gr.id}:${j}"><i></i><div><b>${esc(o.l)}</b>${o.d?`<span>${esc(o.d)}</span>`:''}</div></button>`}).join('')+'</div>'});
  return h+`</div><div class="desp"><button class="btn full" data-a="fGo">Decidir</button></div></div>`}
function vAtend(c){const T=TPL[c.t];let h=`<div class="memo"><div class="mh"><b>Atendimento</b><span class="xs mu">${c.asked.length}/4 perguntas · 0,5h cada</span></div><div class="mb"><div class="story">${T.intro(c)}</div>`;
  c.asked.forEach(id=>{const q=T.atq.find(x=>x.id===id);if(!q)return;h+=`<p class="b" style="font-family:var(--sans);font-size:13px;margin:12px 0 2px">Você: ${esc(q.q)}</p><div class="say">${q.a(c,atqRv(c,q))}</div>`});
  h+=`</div><div class="desp"><label>${c.asked.length<4?'O que você pergunta?':'Hora de fechar o atendimento'}</label>`;
  if(c.asked.length<4)h+=atqOffer(c).map(q=>c.asked.includes(q.id)?'':`<button class="ro" data-a="ask" data-v="${q.id}"><i></i><div><b style="font-weight:500">${esc(q.q)}</b></div></button>`).join('');
  return h+`<button class="btn ${c.asked.length>=2?'':'sec'} full" style="margin-top:6px" data-a="endAt">Encerrar o atendimento</button></div></div>`}
function vConc(c){const I=concInfo(c),P=partes(c);const lines=[advLn(c)];
  return `<div class="memo"><div class="mh"><b>Audiência de conciliação</b><span class="xs mu">${esc(vara(c))}</span></div><div class="mb"><p>Sala pequena, mesa de fórmica, ar-condicionado no máximo. O conciliador lê os nomes: ${esc(P.a)} contra ${esc(P.r)}. ${advT(c)} chega por último.</p><div class="say">${pick(lines)} ${c.lado==='autor'?`${esc(TPL[c.t].conc(c).txt)} <b>${money(I.offer)}</b>. Pegar ou largar.`:`${esc(TPL[c.t].conc(c).txt)} <b>${money(I.offer)}</b>.`}</div><p class="sm" style="font-family:var(--sans)">${c.t==='neg'?`Em jogo: a declaração de inexistência do débito de ${money(c.v.div)}${c.mres&&c.mres.ped&&c.mres.ped.dm?' e o dano moral pedido':''}.`:c.lado==='autor'?`O pedido em dinheiro é de ${money(I.claim)}.`:`O autor pede ${money(I.claim)}.`} ${esc(first(c.cli.n))} te olha, esperando você dizer o que fazer.</p>${leis(['CPC-3',c.rito==='jec'?'L9099-21':'CPC-334','CPC-487'])}</div>
  <div class="desp"><label>Sua orientação</label><button class="ro" data-a="conc" data-v="aceita"><i></i><div><b>${c.lado==='autor'?'Aceitar':'Pagar'} ${money(I.offer)}</b><span>Acordo homologado agora. Fim do processo.</span></div></button><button class="ro" data-a="conc" data-v="contra"><i></i><div><b>Contrapropor ${money(I.counter)}</b><span>Pode fechar melhor. Ou nada.</span></div></button><button class="ro" data-a="conc" data-v="recusa"><i></i><div><b>Recusar e seguir com o processo</b><span>Apostar na sentença.</span></div></button></div></div>`}
function vAij(c){if(!c.ai)return `<div class="memo"><div class="mh"><b>Audiência de instrução e julgamento</b><span class="xs mu">${esc(vara(c))}</span></div><div class="mb"><p>${c.juiz.n} entra, todos se levantam. "Vamos começar. Temos pauta cheia." Do outro lado, ${advT(c)}.</p>${leis(['CPC-459','CPC-457','CPC-364'])}</div><div class="desp"><button class="btn full" data-a="aijGo">Entrar na sala (4h)</button></div></div>`;
  const st=aijSteps(c)[c.ai.i];let h=`<div class="memo"><div class="mh"><b>${esc(st.tit)}</b><span class="xs mu">etapa ${c.ai.i+1} de ${aijSteps(c).length}</span></div><div class="mb"><p>${st.txt}</p></div><div class="desp">`;
  if(st.tp==='choice'){st.opts.forEach((o,j)=>{h+=`<button class="ro ${c.ai.sel===j?'on':''}" data-a="aijC" data-v="${j}" ${c.ai.shown?'disabled':''}><i></i><div><b>${esc(o.l)}</b></div></button>`});
    if(c.ai.shown){const o=st.opts[c.ai.sel];h+=`<div class="alert ${o.ok>=1?'ok':o.ok>0?'':'er'}"><div><b>${o.ok>=1?'Boa.':o.ok>0?'Mais ou menos.':'Erro.'}</b>${esc(o.fb)}<div>${leis(o.a)}</div>${chipsH(c.ai.ch)}</div></div><button class="btn full" data-a="aijN">Continuar</button>`}}
  else{h+=`<label>Perguntas (${c.ai.pk.length}/${st.pick})</label>`;st.qs.forEach((q,j)=>{const done=c.ai.pk.includes(j);h+=`<button class="ro ${done?'on':''}" data-a="aijQ" data-v="${j}" ${done||c.ai.pk.length>=st.pick?'disabled':''}><i></i><div><b>${esc(q.l)}</b>${done?`<span class="serif" style="font-style:italic;font-size:14px;color:var(--tx2)">${esc(q.ans.replace('doutor(a)',DOUT()))}</span>${q.a?`<div>${leis(q.a)}</div>`:''}`:''}</div></button>`});
    if(c.ai.pk.length>=st.pick)h+=`<button class="btn full" data-a="aijN">Continuar</button>`}
  return h+'</div></div>'}
function vAlg(c){const A=TPL[c.t].alg(c),R=c.algR;let h=`<div class="memo"><div class="mh"><b>Alegações finais orais</b><span class="xs mu">20 minutos, prorrogáveis por 10</span></div><div class="mb"><p>"Com a palavra, ${g('a advogada','o advogado')} ${c.lado==='autor'?(c.cli.f?'da autora':'do autor'):(c.cli.f?'da ré':'do réu')}." O silêncio da sala pesa. ${esc(first(c.cli.n))} segura a respiração ao seu lado.</p>${lei('CPC-364')}<p class="sm mu" style="font-family:var(--sans);margin-top:8px">Escreva como se estivesse falando ao juiz: os fatos, as provas produzidas, o direito e o pedido. Citar fato do caso vale mais que juridiquês. E nunca admita nada contra o seu cliente.</p></div><div class="desp">`;
  if(!R)h+=`<textarea data-in="txt" id="ans" placeholder="Excelência, ...">${esc(UI.txt)}</textarea><div style="height:8px"></div><button class="btn full" data-a="alg">Proferir as alegações</button>`;
  else{h+=`<div class="say">${esc(R.t)}</div><div class="pn"><h3>Avaliação <span>${R.r.s}/100</span></h3><div class="pb">${fbList(R.r.fb.map(f=>({ok:f[0],t:f[1],q:f[2]})))}</div></div><div style="height:12px"></div>`;
    h+=`<div class="alert pr"><div><b>${esc(c.juiz.n)} interrompe:</b><span class="serif" style="font-size:15px">"${esc(A.q.q.replace('doutor(a)',DOUT()).replace(/^./,x=>x.toUpperCase()))}"</span></div></div>`;
    if(!R.q)h+=`<textarea data-in="txt2" id="ans" style="min-height:90px" placeholder="Responda em uma ou duas frases.">${esc(UI.txt2)}</textarea><div style="height:8px"></div><button class="btn full" data-a="alg">Responder ao juiz</button>`;
    else h+=`<div class="say">${esc(R.qt)}</div><div class="alert ${R.q.s>=60?'ok':'er'}"><div><b>${R.q.fc?'Resposta contra os fatos do caso.':R.q.s>=80?'Resposta firme.':R.q.s>=60?'Respondeu, sem brilho.':'Resposta fraca.'}</b>${R.q.fc?esc(R.q.fc.msg)+leis(R.q.fc.a):R.q.bad.length?'Cuidado: "'+esc(R.q.bad[0])+'" joga contra o seu cliente.':R.q.s<60?`Faltou enfrentar o ponto que ${c.juiz.f?'a juíza':'o juiz'} levantou.`:`${JZ(c)} anota e acena com a cabeça.`}</div></div><div class="note">Nota final das alegações: <b>${Math.round(c.sc.alg*100)}/100</b>.</div><div style="height:8px"></div><button class="btn full" data-a="algEnd">Encerrar a audiência</button>`}
  return h+'</div></div>'}
function waitInfo(c){const G=S.g;if(c.aud)return `Audiência marcada para <b>${fmtL(c.aud.d)}</b>${c.aud.d===G.date?' (hoje)':''}.`;if(c.wait){const n={despacho:'despacho inicial do juiz',tutela:'decisão sobre a tutela de urgência',agravoRes:'julgamento do agravo no '+TJ(),contestRe:'contestação da ré',saneam:'decisão de saneamento',sentenca:'sentença',embRes:'julgamento dos embargos',recRival:'decisão da parte contrária sobre recurso',acordao:'julgamento do recurso',pagto:'pagamento ou penhora'}[c.wait.ev];return `Aguardando: <b>${n}</b>. O cartório não avisa quando: a intimação chega pelo Diário.`}return 'Aguardando.'}
function vCase(c){syncFase(c);const G=S.g,T=TPL[c.t],P=partes(c);let h=`<button class="lnk sm" data-a="tab" data-v="processos">← Processos</button><div style="height:8px"></div>`;
  h+=`<div class="pn"><div class="li" style="border-bottom:1px solid var(--ln2)"><div class="av">${face(c.cli.n,c.cli.f)}</div><div class="t"><b>${esc(c.cli.n)}</b><span>${c.cli.idade} anos · ${esc(c.cli.prof)}</span><span class="mono xs">${numD(c)}</span></div><div style="width:96px;text-align:right"><div class="xs mu">satisfação <b class="mono">${Math.round(c.sat)}</b></div>${bar(c.sat)}</div></div>
  <div class="kv"><div><label>Ação</label><b>${esc(T.nome)}</b></div><div><label>Você representa</label><b>${c.lado==='autor'?'o autor':'o réu'}</b></div><div><label>Rito</label><b>${c.fase==='atend'||c.fase==='estrat'&&c.lado==='autor'?'a definir':c.rito==='jec'?'Juizado Especial Cível':'Procedimento comum'}</b></div><div><label>Juízo</label><b>${c.fase==='atend'||c.fase==='estrat'||c.fase==='inicial'?'—':esc(vara(c))}</b></div><div><label>Partes</label><b style="white-space:normal;font-weight:500;font-size:12.5px">${esc(P.a)} × ${esc(P.r)}</b></div><div><label>Do outro lado</label><b>${advT(c)}</b></div><div><label>${c.t==='neg'?'Dívida contestada':c.t==='acid'?'Valor cobrado do cliente':'Custo do procedimento'}</label><b class="mono">${money(c.t==='neg'?c.v.div:c.t==='acid'?c.v.dmat+c.v.dmor:c.v.cir)}</b></div><div><label>Estilo do adversário</label><b style="white-space:normal;font-weight:500;font-size:12.5px">${esc(advOf(c).st)}</b></div></div></div>`;
  if(c.prazo)h+=`<div style="height:12px"></div><div class="alert ${prazoCls(c.prazo.ate)==='er'?'er':prazoCls(c.prazo.ate)==='wa'?'':'ok'}"><div><b>Prazo: ${esc(c.prazo.lbl)}. Vence ${fmtL(c.prazo.ate)} (${prazoTxt(c.prazo.ate)}).</b>${leis(c.prazo.a)}</div></div>`;else h+='<div style="height:12px"></div>';
  if(c.fb){h+=`<div class="pn"><h3>${esc(c.fb.tit)}</h3><div class="pb">${c.fb.blocks?blocksFb(c.fb.blocks):fbList(c.fb.items)}${chipsH(c.fb.ch)}<div style="height:10px"></div><button class="btn ${c.prazo?'sec':''} full" data-a="fbOk">${c.prazo?'Fechar este resultado':'Continuar'}</button></div></div><div style="height:12px"></div>`}
  if(c.jcAny&&!c.done&&!c.sent)h+=`<div class="alert"><div><b>Prazo perdido: dá para pedir devolução por justa causa?</b>Só se um evento alheio à sua vontade impediu o ato. Esquecimento ou excesso de trabalho não são justa causa.<div>${leis(['CPC-223'])}</div><div style="height:8px"></div><button class="btn sm sec" data-a="jc2">Pedir devolução do prazo (1h)</button></div></div>`;
  if(c.jc&&!c.done)h+=`<div class="alert er"><div><b>O prazo do rol venceu sem que o jogo oferecesse a ação.</b>Você pode pedir a devolução do prazo por justa causa: evento alheio à sua vontade que impediu a prática do ato.<div>${leis(['CPC-223'])}</div><div style="height:8px"></div><button class="btn sm" data-a="jc">Pedir devolução do prazo — justa causa (1h)</button></div></div>`;
  const audHoje=c.aud&&c.aud.d===G.date&&!c.aud.ok;
  if(!c.done&&(audHoje&&c.aud.tp==='conc'))h+=vConc(c);
  else if(!c.done&&((audHoje&&c.aud.tp==='aij')||c.ai))h+=vAij(c);
  else if(c.done)h+=`<div class="pn"><h3>Encerrado</h3><div class="pb"><p>${c.how==='acordo'?'Acordo homologado.':c.how==='indef'?'Petição inicial indeferida.':c.how==='ext'?'Processo extinto pela ausência do autor.':'Decisão final: '+({proc:'procedente',parc:'parcialmente procedente',improc:'improcedente'}[c.sent&&c.sent.res]||'—')+'.'}</p><p class="sm">Honorários do escritório: <b>${money(c.fee||0)}</b> · sua parte: <b>${money(c.share||0)}</b></p>${c.sent?`<button class="btn sec sm" data-a="reSent" data-v="${c.id}">Reler a sentença</button>`:''}</div></div>`;
  else if(c.fase==='atend')h+=vAtend(c);
  else if(['estrat','replica','saneamento','agravo','pos','cumpr','contrarraz'].includes(c.fase)){if(c.fase==='pos')h+=`<button class="btn sec sm" data-a="reSent" data-v="${c.id}" style="margin-bottom:10px">Reler a sentença</button>`;h+=vForm(c)}
  else if(c.fase==='inicial'||c.fase==='contest')h+=c.m?vMont(c,'case'):`<div class="memo"><div class="mh"><b>${c.fase==='inicial'?'Petição inicial':'Contestação'}</b><span class="xs mu">5h no protocolo</span></div><div class="mb"><p>${c.fase==='inicial'?'Hora de transformar a história em peça. Endereçamento, qualificação, fatos, fundamentos, pedidos, valor da causa e provas.':'Toda a matéria de defesa vai aqui. O que não for impugnado presume-se verdadeiro.'}</p>${leis(c.fase==='inicial'?['CPC-319','CPC-292']:['CPC-335','CPC-336','CPC-341'])}</div><div class="desp"><button class="btn full" data-a="mStart">Abrir o Montador de Peças</button></div></div>`;
  else if(c.fase==='emenda'&&c.m)h+=`<div class="alert"><div><b>Emenda da inicial</b>Corrija só os blocos apontados pelo juiz. Se a emenda não resolver, a inicial é indeferida (art. 321, parágrafo único).</div></div>`+vMont(c,'emenda');
  else if(c.fase==='emenda')h+=`<div class="memo"><div class="mh"><b>Emenda da inicial</b><span class="xs mu">2h</span></div><div class="mb"><p>O juiz mandou corrigir: ${esc(c.emenda.join('; '))}.</p>${lei('CPC-321')}</div><div class="desp"><button class="btn full" data-a="emendar">Emendar e protocolar (2h)</button></div></div>`;
  else if(c.fase==='conc'&&c.aud&&c.aud.d===G.date)h+=vConc(c);
  else if(c.fase==='aij'&&c.aud&&c.aud.d===G.date||c.ai)h+=vAij(c);
  else if(c.fase==='alg')h+=vAlg(c);
  else h+=`<div class="pn"><h3>Andamento</h3><div class="pb sm">${waitInfo(c)}</div></div>`;
  h+=`<div class="pn"><h3>Autos <span>${c.autos.length} ${c.autos.length===1?'ato':'atos'}</span></h3>${c.autos.length?`<ul class="tl">${c.autos.slice().reverse().map(x=>`<li><div class="d">${fmtD(x.d)}</div>${esc(x.t)}</li>`).join('')}</ul>`:'<div class="empty">Ainda não há processo: o caso está no escritório.</div>'}</div>`;
  return h}

/* ---------- janelas ---------- */
function prazoBox(p){if(!p)return '';const skip=[];let d=p.ini;while(d<p.ate){d=addD(d,1);if(isWork(d)&&isRec(d)){if(!skip.includes('recesso'))skip.push('recesso')}else if(isFer(d)&&wd(d)%6)skip.push(ferNome(d)+' ('+fmtDs(d)+')')}
  return `<div class="pz">Publicação: <b>${fmtL(p.ini)}</b>. A contagem começa no primeiro dia útil seguinte. <b>${p.n} dias úteis</b> → vence <b>${fmtL(p.ate)}</b>.${skip.length?' Não contam: '+skip.join(', ')+'.':''}<div>${leis(['CPC-219','CPC-224'].concat(skip.length>(skip.includes('recesso')?1:0)?['CPC-216']:[]).concat(skip.includes('recesso')?['CPC-220']:[]))}</div></div>`}
function vPop(){const G=S.g,P=G.pop[0];if(!P)return '';const c=P.c?byId(P.c):null;
  if(P.k==='sent')return vSent(c,true);
  if(P.k==='dje')return `<div class="ov"><div class="md dje"><div class="mh2"><small>DIÁRIO DA JUSTIÇA ELETRÔNICO · ${TJ()} · ${fmtD(G.date)}</small><h2>${esc(P.tit)}</h2></div><div class="mbd"><div class="proc">Processo ${c?c.num:''} · ${c?esc(vara(c)):''}<br>Cliente: ${c?esc(c.cli.n):''}</div><p style="margin:0">${P.html?P.txt:esc(P.txt)}</p><div style="margin-top:8px">${leis(P.a)}</div>${prazoBox(P.pz)}</div><div class="mft">${c&&!c.done?`<button class="btn sec" data-a="popOpen" data-v="${c.id}">Abrir o processo</button>`:''}<button class="btn" data-a="popOk">Ciente</button></div></div></div>`;
  if(P.k==='novo'){const T=TPL[c.t];return `<div class="ov"><div class="md"><div class="mh2"><small>Novo caso · ${esc(T.area)}</small><h2>${esc(T.nome)}</h2></div><div class="mbd"><div class="row" style="align-items:flex-start;flex-wrap:nowrap"><div class="av" style="width:56px;height:56px">${face(c.cli.n,c.cli.f)}</div><div><b>${esc(c.cli.n)}</b><div class="sm mu">${c.cli.idade} anos · ${esc(c.cli.prof)}</div><p class="sm" style="margin:6px 0 0">${c.lado==='autor'?'Quer entrar com uma ação.':'Foi processado e precisa de defesa.'} ${c.lado==='reu'?`Do outro lado: ${advT(c)}.`:''}</p></div></div></div><div class="mft"><button class="btn sec" data-a="popOk">Depois</button><button class="btn" data-a="popOpen" data-v="${c.id}">Atender agora</button></div></div></div>`}
  if(P.k==='info')return `<div class="ov"><div class="md"><div class="mh2"><small>${esc(P.sub||'Aviso')}</small><h2>${esc(P.tit)}</h2></div><div class="mbd big">${P.txt}</div><div class="mft">${P.c&&c&&!c.done?`<button class="btn sec" data-a="popOpen" data-v="${c.id}">Abrir o processo</button>`:''}<button class="btn" data-a="popOk">Entendi</button></div></div></div>`;
  if(P.k==='miss')return `<div class="ov" style="background:rgba(80,0,0,.7)"><div class="md" style="border-top-color:var(--er)"><div class="mh2"><small style="color:var(--er)">${P.aud?'Audiência perdida':'Prazo perdido'} · ${esc(P.lbl)} · ${P.aud?'era em':'venceu em'} ${fmtD(P.ate)}</small><h2>${c?esc(c.cli.n):''}</h2></div><div class="mbd"><p class="big" style="margin-top:0">${esc(P.t)}</p>${leis(P.a)}${P.rep?`<div class="alert er" style="margin-top:10px"><div><b>Representação na OAB</b>O cliente levou o caso ao Tribunal de Ética.${leis(['EAOAB-34'])}</div></div>`:''}${chipsH(P.ch)}<p class="sm mu">"${esc(MENTOR.t)}: aqui ninguém perde prazo." Você lembra da frase a noite inteira.</p></div><div class="mft"><button class="btn er" data-a="popOk">Assumir o erro</button></div></div></div>`;
  if(P.k==='ev'){const E=EVT.find(e=>e.id===P.id),w=P.who;let h=`<div class="ov"><div class="md"><div class="mh2"><small>Dilema · ${esc(w.r)}</small><h2>${esc(E.tit)}</h2></div><div class="mbd"><div class="row" style="flex-wrap:nowrap;align-items:flex-start"><div class="av" style="width:52px;height:52px">${face(w.n,w.f)}</div><div class="story">${E.scene(w)}</div></div><div style="height:10px"></div>`;
    E.opts.forEach((o,i)=>{h+=`<button class="ro ${P.sel===i?'on':''}" data-a="evC" data-v="${i}" ${P.sel!=null?'disabled':''}><i></i><div><b>${esc(o.l)}</b></div></button>`});
    if(P.sel!=null){const o=E.opts[P.sel];h+=`<div class="alert ${o.ok>=1?'ok':o.ok>0?'':'er'}"><div><b>${o.ok>=1?'Conduta correta.':o.ok>0?'Zona cinzenta.':'Infração.'}</b>${esc(o.fb)}<div>${leis(o.a)}</div>${o.inf?'<div class="er b sm" style="margin-top:4px">Gerou representação no Tribunal de Ética e Disciplina.</div>':''}${chipsH(P.ch)}</div></div>`}
    return h+`</div>${P.sel!=null?'<div class="mft"><button class="btn" data-a="popOk">Continuar</button></div>':''}</div></div>`}
  if(P.k==='epi'){const w=c.win;const head=c.how==='acordo'?'Acordo fechado':['indef','ext'].includes(c.how)?'Processo encerrado sem julgamento do mérito':w>=1?'Vitória':w>0?'Vitória parcial':'Derrota';
    const AT=advT(c),pr=c.adv==='prado'||!c.adv;const rl=w>0&&w<1&&c.how!=='acordo'?`${AT} recolhe os papéis. "Meio a meio, ${DOUT()}. Da próxima vez é inteiro: para mim."`:c.how==='acordo'?`${AT} recolhe os papéis. "Foi um prazer, ${DOUT()}."${pr?' Não pareceu.':''}`:w>=1?(pr?`No corredor, ${AT} passa sem olhar. Depois volta dois passos. "Boa audiência." E vai embora.`:`${AT} aperta sua mão na saída. "Da próxima vez eu ganho."`):(pr?`${AT} ajeita a abotoadura. "Volte quando tiver mais estrada, ${DOUT()}."`:`${AT} guarda o processo na pasta sem dizer nada.`);
    return `<div class="ov"><div class="md" style="border-top-color:${w>=1?'var(--ok)':w>0?'var(--go)':'var(--er)'}"><div class="mh2"><small>${esc(TPL[c.t].nome)} · epílogo</small><h2>${head}</h2></div><div class="mbd"><div class="row" style="flex-wrap:nowrap;align-items:flex-start"><div class="av" style="width:56px;height:56px">${face(c.cli.n,c.cli.f)}</div><div class="story">${TPL[c.t].epi(c,w>=.5||c.how==='acordo')}</div></div><p class="sm mu">${rl}</p><div class="pz">${c.hon&&c.hon.fixo?`Honorários fixos já recebidos no contrato: <b>${money(c.hon.fixo)}</b><br>`:''}Honorários de êxito e sucumbência: <b>${money(c.fee||0)}</b> · sua parte (25%): <b>${money(c.share||0)}</b></div>${chipsH(P.ch)}</div><div class="mft"><button class="btn" data-a="popOk">Fechar o processo</button></div></div></div>`}
  if(P.k==='ted'){const t=['','Censura','Suspensão','Exclusão'][P.lv];return `<div class="ov" style="background:rgba(30,0,0,.75)"><div class="md" style="border-top-color:var(--er)"><div class="mh2"><small style="color:var(--er)">Tribunal de Ética e Disciplina · OAB/${S.uf}</small><h2>${t}</h2></div><div class="mbd big"><p>${P.lv===3?'Seis representações. O Conselho Seccional decide pela sua exclusão dos quadros da Ordem. A carteira vermelha volta para a gaveta da Seccional.':P.lv===2?'O Tribunal de Ética aplica a suspensão. Clientes leem no Diário. Alguns ligam; outros não ligam mais.':'O Tribunal de Ética aplica a pena de censura. Fica no seu histórico. A próxima será pior.'}</p>${leis(['EAOAB-35',P.lv===3?'EAOAB-38':'EAOAB-36'])}</div><div class="mft"><button class="btn er" data-a="popOk">${P.lv===3?'Fim da carreira':'Seguir em frente'}</button></div></div></div>`}
  return ''}
function vSent(c,isPop){const st=c.sent,T=sentText(c),w=winOf(c),cls=w>=1?'w':w>0?'p':'l',n=T.L.length;
  return `<div class="sent"><div class="pg"><div class="hdr"><b>PODER JUDICIÁRIO · ${TJ()}</b>${esc(vara(c))}<br><span class="mono">Processo ${c.num}</span></div><p style="text-align:center;letter-spacing:.14em;font-family:var(--sans);font-weight:700;animation-delay:.1s">SENTENÇA</p>${T.L.map((l,i)=>`<p class="${i===n-3?'dsp':''}" style="animation-delay:${.5+i*.9}s">${l}</p>`).join('')}
  <div class="stamp ${cls}" style="animation-delay:${.5+(n-3)*.9+.6}s">${T.lbl}</div>
  <div class="after" style="animation-delay:${.5+n*.9+.4}s"><div class="hr"></div><b class="sm" style="font-family:var(--sans)">Por que ${w>=1?'você venceu':w>0?'a vitória foi parcial':'você perdeu'}</b><ul class="fb" style="margin-top:6px">${st.F.map(f=>`<li class="${f.sg>0?'y':f.sg<0?'n':''}"><i>${f.sg>0?'+':f.sg<0?'−':'·'}</i><div class="sm" style="font-family:var(--sans)">${esc(f.t)}${f.a?`<div>${leis(f.a)}</div>`:''}</div></li>`).join('')}</ul><p class="xs mu" style="font-family:var(--sans)">Força da causa estimada: ${Math.round(st.s*100)}/100 · chance de êxito: ${Math.round(st.p*100)}%</p><button class="btn full" data-a="${isPop?'popOk':'sentClose'}">${isPop?'Continuar':'Fechar'}</button></div></div></div>`}
function vNews(){return `<div class="ov" data-a="newsClose"><div class="md" data-stop="1"><div class="mh2"><small>Novidades · versão ${VERSION}</small><h2>${esc(CHANGELOG[0].t)}</h2></div><div class="mbd">${CHANGELOG.map(c=>`<div class="b sm">${c.v} · ${c.d}</div><ul class="fb">${c.i.map(x=>`<li class="y"><i>✓</i><div class="sm">${esc(x)}</div></li>`).join('')}</ul>`).join('<div class="hr"></div>')}<div class="hr"></div><div class="b sm">Próximas atualizações</div><ul class="fb">${ROADMAP.map(x=>`<li><i>○</i><div class="sm">${esc(x)}</div></li>`).join('')}</ul><p class="note">Seu save continua valendo nas próximas versões.</p></div><div class="mft"><button class="btn" data-a="newsClose">Fechar</button></div></div></div>`}
function vConfirm(){return `<div class="ov"><div class="md"><div class="mh2"><small>Nova carreira</small><h2>Começar do zero?</h2></div><div class="mbd"><p>A carreira atual será apagada: processos, clientes, Vade Mecum estudado e o placar contra o ${RIVAL.t}.</p></div><div class="mft"><button class="btn sec" data-a="confNo">Cancelar</button><button class="btn er" data-a="new">Apagar e recomeçar</button></div></div></div>`}
function vFim(){const G=S.g;return `<div class="cover"><div class="frame"></div><div class="kick">Fim da carreira</div><h1 style="font-size:clamp(40px,9vw,72px)">EXCLUÍD${g('A','O')}</h1><div class="tag">O Tribunal de Ética falou por último.</div><div class="lines">${G.stats.closed} processos encerrados · ${G.stats.won} vitórias · ${G.inf} representações · ${S.vm.n} artigos estudados.<br><br>A advocacia é feita de prazos, de clientes e de ética. Faltou a terceira.</div><div class="btns"><button class="btn gold" data-a="new">Nova carreira</button><button class="btn sec" data-a="cover">Capa</button></div></div>`}

/* ---------- render ---------- */
function render(){let h='';
  if(UI.screen==='cover')h=vCover();else if(UI.screen==='setup')h=vSetup();
  else if(S){switch(S.phase){case 'tut':h=vTut();break;case 'oab1':h=vOab1();break;case 'oab1res':h=vOab1Res();break;case 'oab2':h=vOab2();break;case 'oab2res':h=vOab2Res();break;case 'posse':h=vPosse();break;case 'fim':h=vFim();break;
    default:{let inner;if(UI.open&&byId(UI.open))inner=vCase(byId(UI.open));else inner={painel:vPainel,processos:vProcessos,prazos:vPrazos,clientes:vClientes,escritorio:vEscritorio,vade:vVade,oab:vOAB}[UI.tab]();h=shell(inner);if(S.g.pop.length)h+=vPop();if(UI.sent)h+=vSent(byId(UI.sent),false)}}
    if(S.phase!=='car'&&UI.tab==='vade'&&S.phase!=='fim')h=preBar('Vade Mecum')+`<div class="wrap" style="margin:0 auto;max-width:760px"><button class="lnk sm" data-a="vmBack">← Voltar</button><div style="height:8px"></div>${vVade()}</div>`;}
  if(UI.vm)h+=vDrawer();if(UI.modal==='news')h+=vNews();if(UI.modal==='confirm')h+=vConfirm();
  if(UI.toast)h+=`<div class="toast">${esc(UI.toast)}</div>`;
  const fa=document.activeElement,fid=fa&&fa.dataset?fa.dataset.in:null,pos=fa&&fa.selectionStart;
  $.innerHTML=h;document.body.classList.toggle('dark',UI.screen==='cover'||(S&&S.phase==='fim'&&UI.screen==='game'));
  if(fid){const t=$.querySelector(`[data-in="${fid}"]`);if(t){t.focus();try{t.selectionStart=t.selectionEnd=pos}catch(e){}}}
}
setInterval(()=>{if(!S||UI.screen!=='game')return;let dl,tot;if(S.phase==='oab1'&&!S.ex.shown&&!S.ex.pause){dl=S.ex.dl;tot=QT}else if(S.phase==='oab2'&&S.p2.st==='peca'){dl=S.p2.dl;tot=PT}else return;
  const left=Math.max(0,dl-Date.now()),t=document.getElementById('tt'),b=document.getElementById('tb'),x=document.getElementById('tx');if(t)t.textContent=fmtT(left);if(b)b.style.width=(left/tot*100)+'%';if(x)x.classList.toggle('low',left<tot*.15);
  if(left<=0){if(S.phase==='oab1'){for(let i=S.ex.i;i<20;i++)if(S.ex.ans[i]==null)S.ex.ans[i]=-1;S.phase='oab1res';toast('Tempo esgotado. Prova recolhida.')}else{examPeca()}save();render()}},500);

/* ---------- ações ---------- */
function startOab1(){const used=new Set(S.usedQ);let pickQ=[];Object.keys(DIST).forEach(d=>{let pool=QB.map((q,i)=>i).filter(i=>QB[i].d===d&&!used.has(i));if(pool.length<DIST[d])pool=QB.map((q,i)=>i).filter(i=>QB[i].d===d);pickQ=pickQ.concat(shuffle(pool).slice(0,DIST[d]))});pickQ=shuffle(pickQ);
  S.usedQ=S.usedQ.concat(pickQ);S.ex={q:pickQ,perm:pickQ.map(()=>shuffle([0,1,2,3])),i:0,ans:[],dl:Date.now()+QT,shown:false};S.phase='oab1';save();render();toTop()}
function startOab2(){const c={t:'neg',num:'—',lado:'autor',rito:'jec',rev:{prot:1,ext:1},asked:[],sc:{},autos:[],m:null};Object.assign(c,TPL.neg.make());c.rito='jec';c.hid.outra=false;c.hid.prot=true;c.rev={prot:1};
  S.p2={st:'peca',c,dl:Date.now()+PT,sc:0,res:null,disc:(q=>({q,perm:q.map(()=>shuffle([0,1,2,3])),i:0,ans:[]}))(shuffle(D2.map((x,i)=>i)).slice(0,4))};S.phase='oab2';save();render();toTop()}
function examPeca(){const P=S.p2;if(P.st!=='peca')return;mInit(P.c);P.sc=protocol(P.c,'exam')||0;P.res=P.c.mres.res;P.st='disc';save();render();toTop()}
function curCase(){return UI.open?byId(UI.open):null}
function act(a,v,el){const G=S&&S.g,c=S&&S.phase==='car'?curCase():(S&&S.phase==='oab2'?S.p2.c:null);
  switch(a){
  case 'new':store.del(KEY);S=null;UI.modal=null;UI.screen='setup';UI.setup.nome='';render();toTop();break;
  case 'askNew':UI.modal='confirm';render();break;case 'confNo':UI.modal=null;render();break;
  case 'cover':UI.screen='cover';UI.open=null;UI.vm=null;render();toTop();break;
  case 'continue':S=load();if(S){postLoad();UI.screen='game';UI.tab='painel';UI.open=null;if(S.seenV!==VERSION){S.seenV=VERSION;UI.modal='news';save()}render();toTop()}break;
  case 'sx':UI.setup.sx=v;render();break;
  case 'start':newGame();UI.screen='game';render();toTop();break;
  case 'news':UI.modal='news';render();break;case 'newsClose':UI.modal=null;render();break;
  case 'mute':UI.mute=!UI.mute;store.set('suits_mute',UI.mute?'1':'0');render();break;
  case 'tut':S.tut++;save();render();toTop();break;
  case 'tutPick':S.tutA=v;snd(v===addUteis('2027-04-16',5)?'ok':'no');save();render();break;
  case 'oab1':startOab1();break;
  case 'ans1':{if(S.ex.shown)return;const oi=S.ex.perm[S.ex.i][+v];S.ex.ans[S.ex.i]=oi;S.ex.shown=true;S.ex.pause=Date.now();snd(oi===QB[S.ex.q[S.ex.i]].c?'ok':'no');save();render();break}
  case 'next1':if(S.ex.pause){S.ex.dl+=Date.now()-S.ex.pause;S.ex.pause=null}if(S.ex.i<19){S.ex.i++;S.ex.shown=false}else S.phase='oab1res';save();render();toTop();break;
  case 'tutRetry':S.tutA=null;save();render();break;
  case 'retry1':S.exN++;S.g.date=addD(S.g.date,120);S.g.cx-=300;S.g.ind.st=clamp(S.g.ind.st+10,0,100);startOab1();break;
  case 'oab2':startOab2();break;
  case 'ans2':{const D=S.p2.disc;if(D.ans[D.i]!=null)return;const pm=(D.perm&&D.perm[D.i])||[0,1,2,3],oi=pm[+v];D.ans[D.i]=oi;snd(oi===D2[D.q[D.i]].c?'ok':'no');save();render();break}
  case 'next2':{const D=S.p2.disc;if(D.i<3)D.i++;else S.phase='oab2res';save();render();toTop();break}
  case 'retry2':S.exN++;S.g.date=addD(S.g.date,120);S.g.cx-=300;S.g.ind.st=clamp(S.g.ind.st+8,0,100);startOab2();break;
  case 'posse':S.phase='posse';save();render();toTop();break;
  case 'prometo':S.g.oab=`OAB/${S.uf} ${RI(140,320)}.${String(RI(0,999)).padStart(3,'0')}`;snd('win');startCareer();render();toTop();break;
  case 'tab':UI.tab=v;UI.open=null;render();toTop();break;
  case 'open':case 'popOpen':if(a==='popOpen'){G.pop.shift()}UI.open=v;UI.tab='processos';save();render();toTop();break;
  case 'popOk':{const P=G.pop.shift();if(P&&P.k==='ted'&&P.lv===3){S.phase='fim'}save();render();break}
  case 'evC':evChoose(+v);break;
  case 'end':if(G.pop.length)return;endDay();render();toTop();break;
  case 'ff':if(G.pop.length)return;fastForward();break;
  case 'night':if(G.night)return;G.night=true;G.h+=4;bump('st',3);toast('Café, silêncio e a luz da tela. +4 horas.');save();render();break;
  case 'ask':ask(c,v);break;case 'endAt':if(c.asked.length<1)return toast('Faça ao menos uma pergunta.');endAtend(c);break;
  case 'fSel':{const [gid,j]=v.split(':');c.fa=c.fa||{};c.fa[gid]=+j;if(gid==='rec')delete c.fa.prep;render();break}
  case 'fGo':submitForm(c);break;
  case 'fbOk':c.fb=null;save();render();toTop();break;
  case 'mStart':c.m={i:0,a:{}};save();render();toTop();break;
  case 'mSel':mInit(c).a[montBlocks(c)[c.m.i].k].sel=+v;render();break;
  case 'mVal':mInit(c).a.valor.sel=+v;render();break;
  case 'mChk':{const A=mInit(c).a[montBlocks(c)[c.m.i].k];A.ch[v]=!A.ch[v];render();break}
  case 'mUp':case 'mDn':{const A=mInit(c).a.fatos,i=+v,j=a==='mUp'?i-1:i+1;[A.ord[i],A.ord[j]]=[A.ord[j],A.ord[i]];render();break}
  case 'mOff':{const A=mInit(c).a.fatos;A.off[v]=!A.off[v];render();break}
  case 'mImp':{const [i,x]=v.split(':');mInit(c).a.imp.v[i]=+x;render();break}
  case 'mNext':{const b=montBlocks(c)[c.m.i],A=c.m.a[b.k];if((b.k==='end'||b.k==='prelim'||b.k==='valor')&&A.sel==null)return toast('Escolha uma opção.');if(b.k==='imp'&&Object.keys(A.v).length<b.items.length)return toast('Decida sobre todos os fatos.');
    if(['qual','ped','prov','fund'].includes(b.k)){const n=Object.values(A.ch||{}).filter(Boolean).length;if(!n)return toast('Marque ao menos uma opção.');if(b.k==='fund'&&(n<2||n>4))return toast('Escolha de 2 a 4 fundamentos.')}
    if(c.m.em){const B=montBlocks(c);let j=c.m.i+1;while(j<B.length&&!c.m.em.includes(B[j].k))j++;if(j<B.length)c.m.i=j;save();render();toTop();break}
    c.m.i++;mInit(c);save();render();toTop();break}
  case 'mPrev':{if(c.m.em){const B=montBlocks(c);let j=c.m.i-1;while(j>=0&&!c.m.em.includes(B[j].k))j--;if(j>=0)c.m.i=j}else c.m.i=Math.max(0,c.m.i-1);render();toTop();break}
  case 'mProt':{const b=montBlocks(c)[c.m.i];if(b.k==='valor'&&c.m.a.valor.sel==null)return toast('Escolha o valor da causa.');protocol(c,'case');break}
  case 'mEmenda':{const b=montBlocks(c)[c.m.i];if(b.k==='valor'&&c.m.a.valor.sel==null)return toast('Escolha o valor da causa.');protocol(c,'emenda');break}
  case 'mExam':{const b=montBlocks(c)[c.m.i];if(c.m.a[b.k]&&c.m.a[b.k].sel==null&&b.k==='valor')return toast('Escolha o valor da causa.');examPeca();break}
  case 'jc':{if(!c||!c.jc||!spend(1))return;c.jc=0;if(chance(.85)){c.noTest=0;c.sc.prova+=.22;pz(c,'saneamento',5,'Rol de testemunhas (prazo devolvido)',['CPC-223','CPC-357']);c.fase='saneamento';if(c.aud&&c.aud.tp==='aij'&&c.aud.d<=addUteis(S.g.date,5))c.aud.d=addUteis(S.g.date,RI(12,18));dje(c,'Justa causa reconhecida: prazo devolvido','Comprovada a justa causa, devolvo à parte ré o prazo de 5 dias para apresentar o rol de testemunhas.',['CPC-223'])}else dje(c,'Pedido de devolução de prazo indeferido','Não comprovada a justa causa. Mantida a preclusão da prova testemunhal.',['CPC-223']);save();render();toTop();break}
  case 'jc2':{if(!c||!c.jcAny||!spend(1))return;const tp=c.jcAny.tp;c.jcAny=null;
    if(chance(.15)){c.wait=null;if(tp==='contest'){c.revel=0;c.sc.pen=Math.max(0,c.sc.pen-.42);pz(c,'contest',5,'Contestação (prazo devolvido)',['CPC-223','CPC-335']);c.fase='contest'}else{c.sc.pen=Math.max(0,c.sc.pen-.07);pz(c,'replica',5,'Réplica (prazo devolvido)',['CPC-223','CPC-350']);c.fase='replica'}
      dje(c,'Justa causa reconhecida: prazo devolvido','O juiz aceitou a justificativa e devolveu o prazo de 5 dias.',['CPC-223'])}
    else{bump('jz',-2);dje(c,'Pedido de devolução de prazo indeferido','Justa causa é o evento alheio à vontade da parte que a impediu de praticar o ato (art. 223, §1º). Não é o caso. Mantida a preclusão.',['CPC-223'])}
    save();render();toTop();break}
  case 'emendar':if(c.mA&&c.emK&&c.emK.length){const B=montBlocks(c);c.m={i:B.findIndex(b=>c.emK.includes(b.k)),a:JSON.parse(JSON.stringify(c.mA)),em:c.emK.slice()};save();render();toTop();break}
    if(!spend(2))return;c.emenda=[];auto(c,'Emenda à inicial protocolada.');c.prazo=null;waitEv(c,'despacho',RI(3,6));fx([['jz',-1]]);save();render();break;
  case 'conc':concDo(c,v);break;
  case 'aijGo':aijStart(c);break;case 'aijC':aijChoose(c,+v);break;case 'aijQ':aijAsk(c,+v);break;case 'aijN':aijNext(c);break;
  case 'alg':algSubmit(c);break;case 'algEnd':algFinish(c);break;
  case 'reSent':UI.sent=v;render();break;case 'sentClose':UI.sent=null;render();break;
  case 'vm':UI.vm=v;save();render();break;case 'vmClose':UI.vm=null;render();break;
  case 'locked':toast('Artigo lacrado: ele abre quando aparecer no jogo.');break;
  case 'vmTab':UI.prevPhaseTab=UI.tab;UI.tab='vade';render();toTop();break;
  case 'vmBack':UI.tab='painel';render();toTop();break;
  case 'vc':UI.vc=v;render();break;case 'vf':UI.vf=!UI.vf;render();break;
  case 'fav':S.vm.fav[v]=!S.vm.fav[v];save();render();break;
  case 'hl':{const sel=String(window.getSelection?window.getSelection():'').trim();if(sel.length<3)return toast('Selecione um trecho do texto primeiro.');const A=getArt(v);if(!A.t.includes(sel))return toast('Selecione dentro do texto do artigo.');S.vm.hl[v]=(S.vm.hl[v]||[]).concat([sel]);save();render();break}
  case 'unhl':S.vm.hl[v]=[];save();render();break;
  }
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-a]');if(!b||b.disabled)return;if(b.classList.contains('ov')&&e.target!==b)return;act(b.dataset.a,b.dataset.v,b)});
document.addEventListener('input',e=>{const t=e.target,k=t.dataset&&t.dataset.in;if(!k)return;if(k==='nome')UI.setup.nome=t.value;else if(k==='vq'){UI.vq=t.value;render()}else if(k==='txt')UI.txt=t.value;else if(k==='txt2')UI.txt2=t.value});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset&&t.dataset.ch==='uf')UI.setup.uf=t.value});
document.addEventListener('keydown',e=>{const k=(e.key||'').toLowerCase(),tg=e.target&&e.target.tagName;if(S&&UI.screen==='game'&&!/INPUT|TEXTAREA|SELECT/.test(tg)){
    if(S.phase==='oab1'&&'abcd'.includes(k)&&k.length===1&&!S.ex.shown){act('ans1',String('abcd'.indexOf(k)));return}
    if(S.phase==='oab1'&&k==='enter'&&S.ex.shown){act('next1');return}
    if(S.phase==='oab2'&&S.p2.st==='disc'&&'abcd'.includes(k)&&k.length===1&&S.p2.disc.ans[S.p2.disc.i]==null){act('ans2',String('abcd'.indexOf(k)));return}
    if(S.phase==='oab2'&&S.p2.st==='disc'&&k==='enter'&&S.p2.disc.ans[S.p2.disc.i]!=null){act('next2');return}}
  if(e.key==='Escape'){if(UI.vm){UI.vm=null;render()}else if(UI.modal){UI.modal=null;render()}}});
if(location.hash==='#dev')window.__suits={get S(){return S},act,render,UI};
